/**
 * Embedded XALEN WASM v0.6.0 binary.
 * Ensures the WebAssembly module is self-contained within the bundled Edge Function
 * without relying on filesystem access (which fails in deployed Supabase Edge Runtime containers).
 */

const XALEN_WASM_BASE64 = "";

let cachedWasmBytes: Uint8Array | null = null;

export function getXalenWasmBytes(): Uint8Array {
  if (cachedWasmBytes) {
    return cachedWasmBytes;
  }

  const globalObj = globalThis as any;
  if (typeof globalObj.Buffer !== "undefined") {
    const buf = globalObj.Buffer.from(XALEN_WASM_BASE64, "base64");
    cachedWasmBytes = new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
    return cachedWasmBytes;
  }

  const atobFn = typeof globalObj.atob === "function" ? globalObj.atob : (s: string) => s;
  const binary = atobFn(XALEN_WASM_BASE64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  cachedWasmBytes = bytes;
  return bytes;
}
